.qz27 *{box-sizing:border-box}
.qz27 .hd{font-size:17px;font-weight:650;margin:0 0 2px}
.qz27 .sub{font-size:13px;color:var(--ink2);margin:0 0 14px}
.qz27 .lbl{display:block;font-size:12px;font-weight:600;letter-spacing:.03em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}
.qz27 .chips{display:flex;flex-wrap:wrap;gap:6px}
.qz27 .chip{font:inherit;font-size:12.5px;padding:5px 12px;border-radius:999px;border:1px solid var(--ring);
  background:transparent;color:var(--ink2);cursor:pointer}
.qz27 .chip:hover{border-color:var(--muted)}
.qz27 .chip[aria-pressed="true"]{background:var(--ink);color:var(--s1);border-color:var(--ink)}
.qz27 .chip[disabled]{opacity:.32;cursor:not-allowed}
.qz27 .foot{margin-top:14px;font-size:11.5px;color:var(--muted)}
@media (max-width:600px){.qz27{padding:14px}}
.qz27 .q{margin-bottom:13px}
.qz27 .q.off{display:none}
.qz27 .res{margin-top:18px;padding-top:16px;border-top:1px solid var(--grid)}
.qz27 .empty{font-size:13.5px;color:var(--muted);margin:0}
.qz27 .row{display:grid;grid-template-columns:24px 1fr;gap:11px;align-items:start;margin-bottom:13px}
.qz27 .n{font-size:12px;font-variant-numeric:tabular-nums;color:var(--muted);padding-top:2px}
.qz27 .nm{font-size:15.5px;font-weight:650;margin:0}
.qz27 .nm span{font-weight:400;font-size:12.5px;color:var(--muted);margin-left:6px}
.qz27 .tr{height:10px;background:var(--bar);border-radius:5px;margin:6px 0 5px;overflow:hidden}
.qz27 .fl{display:block;height:10px;background:var(--accent2);border-radius:5px;transition:width .35s ease}
.qz27 .row.win .fl{background:var(--accent)}
.qz27 .why{font-size:13px;color:var(--ink2);margin:0}
.qz27 .why b{font-weight:650;color:var(--ink)}
.qz27 .rst{font:inherit;font-size:12.5px;background:none;border:0;color:var(--muted);text-decoration:underline;cursor:pointer;padding:0}
