ion":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Ball Control","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — Maestro (98)","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Passing","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — Creator (98)","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":3},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Scoring","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — Finisher (99)","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":4},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Defending","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — Boss (98)","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":5},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Physical","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — Boss (97)","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":6}],"direction":null,"format":"","indent":0,"type":"list","version":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Two things the quiz can't weigh. ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"Your club's shape matters more than your preference","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" — a team of Magicians loses to an organised side, and the Recycler nobody wants to play is often why good clubs win. And ","type":"extended-text","version":1},{"detail":0,"format":1,"mode":"normal","style":"","text":"perks amplify habits rather than creating them","type":"extended-text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":": Cut Back Specialist does nothing for a player who cuts inside and shoots every time.","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Keepers are a different question","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"There are only two keeper archetypes and the choice isn't really about attributes — it's whether your defence plays a high line. Shot Stopper is built to keep the ball out and nothing else. Sweeper Keeper is comfortable receiving back passes and rushing off the line, which is an asset behind a high line and a liability behind a defence that just clears it.","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Frequently asked questions","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"extended-heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Which archetype is best in Pro Clubs?","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"There isn't one. Archetypes are balanced against each other rather than ranked. The strongest pick is the one filling a gap in your club.","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Can I change archetype later?","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Yes, though it resets the progression tied to that archetype.","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Does this account for playstyles?","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"extended-heading","version":1,"tag":"h3"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Not yet — it scores attribute ceilings only. Signature playstyles and the PlayStyle+ options attached to each specialization are a separate layer on top of the archetype choice.","type":"extended-text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1}],"direction":null,"format":"","indent":0,"type":"root","version":1}}

